// Package codegen writes Go source code for an ir.Model.
package codegen

import (
	"bytes"
	"embed"
	"fmt"
	"go/format"
	"path"
	"slices"
	"strconv"
	"strings"
	"text/template"
	"unicode"

	"github.com/dheins/go-openapi/ir"
)

//go:embed templates/*.tmpl
var templateFiles embed.FS

const oapiImport = "github.com/dheins/go-openapi/oapi"

// Options configures generated models.
type Options struct {
	// Package is the Go package name of the generated files.
	Package string
	// Source names the input document in the generated file header.
	Source string
	// Title describes the API in the package documentation.
	Title string
	// Document is the OpenAPI document as JSON. Server embeds it (as
	// openapi.json) so the server can serve it with server.WithDocument.
	Document []byte
	// OperationsPackage, if set, makes Server put the request and response
	// types of the operations in a package of their own, in the
	// subdirectory of that name, imported as OperationsImport; the server
	// package keeps a small handler file per operation. ModelsPackage and
	// ModelsImport do the same for the schema types, which otherwise go
	// with the operations. Without either, all files are one package.
	OperationsPackage string
	OperationsImport  string
	ModelsPackage     string
	ModelsImport      string
	// TypesPackage and TypesImport, if set, make Client use the
	// operations' package of a server or client generated before, by its
	// name and import path, instead of generating the types again.
	TypesPackage string
	TypesImport  string
}

// layout says which package each kind of generated code goes to, by
// import path; "" is the package of Options.Package.
type layout struct {
	opsPkg, opsImport       string
	modelsPkg, modelsImport string
}

func layoutOf(opts Options) (layout, error) {
	l := layout{
		opsPkg: opts.OperationsPackage, opsImport: opts.OperationsImport,
		modelsPkg: opts.ModelsPackage, modelsImport: opts.ModelsImport,
	}
	if (l.opsPkg == "") != (l.opsImport == "") || (l.modelsPkg == "") != (l.modelsImport == "") {
		return layout{}, fmt.Errorf("codegen: a separate package needs both a name and an import path")
	}
	if l.modelsPkg == "" {
		l.modelsPkg, l.modelsImport = l.opsPkg, l.opsImport
	}
	return l, nil
}

// File is one generated source file.
type File struct {
	Name    string
	Content []byte
}

// Models generates one file per root type of m (a component schema with
// the types derived from it), plus doc.go.
func Models(m *ir.Model, opts Options) ([]File, error) {
	g, err := newGenerator(opts)
	if err != nil {
		return nil, err
	}
	if err := g.models(m); err != nil {
		return nil, err
	}
	return g.files, nil
}

type generator struct {
	opts Options
	// self is the import path of the package being generated, as in
	// layout; lay says where the other generated code is.
	self string
	lay  layout
	// vars are the package-level variables declared so far, across files.
	vars map[string]bool
	// params are the variables describing parameters, shared by a
	// package's client functions and handlers.
	params    map[*ir.Param]string
	files     []File
	fileNames map[string]bool
}

func newGenerator(opts Options) (*generator, error) {
	if opts.Package == "" {
		return nil, fmt.Errorf("codegen: package name is required")
	}
	return &generator{opts: opts, vars: map[string]bool{}, params: map[*ir.Param]string{}, fileNames: map[string]bool{}}, nil
}

func (g *generator) models(m *ir.Model) error {
	var roots []*ir.Type
	byRoot := make(map[*ir.Type][]*ir.Type)
	for _, t := range m.Types {
		if _, ok := byRoot[t.Root]; !ok {
			roots = append(roots, t.Root)
		}
		byRoot[t.Root] = append(byRoot[t.Root], t)
	}

	g.add("doc.go", g.docFile())
	for _, root := range roots {
		types := byRoot[root]
		content, err := g.render("types", types, func(f *fileGen) {
			for _, t := range types {
				if t.Kind != ir.Alias {
					f.imp(oapiImport, "oapi")
				}
			}
		})
		if err != nil {
			return fmt.Errorf("generating %s: %w", root.Name, err)
		}
		g.add(fileName(root.Name), content)
	}
	return nil
}

// add records a file, renaming it if the name is taken.
func (g *generator) add(name string, content []byte) {
	unique := name
	for i := 2; g.fileNames[unique]; i++ {
		unique = strings.TrimSuffix(name, ".go") + strconv.Itoa(i) + ".go"
	}
	g.fileNames[unique] = true
	g.files = append(g.files, File{Name: unique, Content: content})
}

func (g *generator) header() string {
	source := g.opts.Source
	if source == "" {
		source = "an OpenAPI document"
	}
	return fmt.Sprintf("// Code generated by goapi from %s. DO NOT EDIT.\n\n", source)
}

func (g *generator) docFile() []byte {
	var b strings.Builder
	b.WriteString(g.header())
	about := "an OpenAPI document"
	if g.opts.Title != "" {
		about = g.opts.Title
	}
	fmt.Fprintf(&b, "// Package %s contains Go types for the schemas of %s.\n", g.opts.Package, about)
	fmt.Fprintf(&b, "//\n// Every type has a Validate method that checks the constraints of its\n")
	fmt.Fprintf(&b, "// schema; decoding JSON reports missing required properties and values\n")
	fmt.Fprintf(&b, "// of the wrong type.\npackage %s\n", g.opts.Package)
	return []byte(b.String())
}

// render executes the template name with data into a formatted Go file.
// setup can register imports the template uses literally.
func (g *generator) render(name string, data any, setup func(*fileGen)) ([]byte, error) {
	f := &fileGen{gen: g, imports: map[string]string{}}
	if setup != nil {
		setup(f)
	}
	tmpl, err := template.New("go").Funcs(f.funcs()).ParseFS(templateFiles, "templates/*.tmpl")
	if err != nil {
		return nil, err
	}
	var body bytes.Buffer
	if err := tmpl.ExecuteTemplate(&body, name, data); err != nil {
		return nil, err
	}

	var out bytes.Buffer
	out.WriteString(g.header())
	fmt.Fprintf(&out, "package %s\n\n", g.opts.Package)
	if len(f.imports) > 0 {
		// Standard library first, then other modules, as goimports does.
		var std, other []string
		for p := range f.imports {
			if first, _, _ := strings.Cut(p, "/"); strings.Contains(first, ".") {
				other = append(other, p)
			} else {
				std = append(std, p)
			}
		}
		slices.Sort(std)
		slices.Sort(other)
		writeImport := func(p string) {
			switch name := f.imports[p]; {
			case name == "_":
				// Imported for its side effects, such as embed.
				fmt.Fprintf(&out, "\t_ %q\n", p)
			case name != path.Base(p):
				fmt.Fprintf(&out, "\t%s %q\n", name, p)
			default:
				fmt.Fprintf(&out, "\t%q\n", p)
			}
		}
		out.WriteString("import (\n")
		for _, p := range std {
			writeImport(p)
		}
		if len(std) > 0 && len(other) > 0 {
			out.WriteString("\n")
		}
		for _, p := range other {
			writeImport(p)
		}
		out.WriteString(")\n")
	}
	for _, v := range f.varDecls {
		out.WriteString("\n" + v + "\n")
	}
	out.Write(body.Bytes())

	formatted, err := format.Source(out.Bytes())
	if err != nil {
		return nil, fmt.Errorf("formatting generated code: %w\n%s", err, out.Bytes())
	}
	return formatted, nil
}

// fileGen collects what one file needs while it is rendered.
type fileGen struct {
	gen      *generator
	imports  map[string]string // path -> package name
	varDecls []string
	// declared are the variables declared, by hint and value, so that the
	// same one is declared once.
	declared map[[2]string]string
	// patterns are the variables of the patterns of patternProperties,
	// by type and pattern.
	patterns map[[2]string]string
}

// patternVar returns the variable holding pattern p, compiled, for the
// properties of type typeName, declaring it on first use.
func (f *fileGen) patternVar(typeName, p string) string {
	key := [2]string{typeName, p}
	if v, ok := f.patterns[key]; ok {
		return v
	}
	if f.patterns == nil {
		f.patterns = map[[2]string]string{}
	}
	v := f.declareVar(lowerFirst(typeName)+"PropertyPattern",
		fmt.Sprintf("%s.MustCompilePattern(%s)", f.imp(oapiImport, "oapi"), strconv.Quote(p)))
	f.patterns[key] = v
	return v
}

// matchesPatterns returns the condition under which name, a Go string
// expression, matches one of the patterns of type typeName.
func (f *fileGen) matchesPatterns(typeName string, patterns []string, name string) string {
	conds := make([]string, len(patterns))
	for i, p := range patterns {
		conds[i] = f.patternVar(typeName, p) + ".Check(" + name + ") == nil"
	}
	return strings.Join(conds, " || ")
}

func (f *fileGen) imp(path, name string) string {
	f.imports[path] = name
	return name
}

// declareVar adds a package-level variable named after hint, unique
// across all generated files, and returns its name.
func (f *fileGen) declareVar(hint, init string) string {
	if name, ok := f.declared[[2]string{hint, init}]; ok {
		return name
	}
	if f.declared == nil {
		f.declared = map[[2]string]string{}
	}
	name := hint
	defer func() { f.declared[[2]string{hint, init}] = name }()
	for i := 2; f.gen.vars[name]; i++ {
		name = hint + strconv.Itoa(i)
	}
	f.gen.vars[name] = true
	f.varDecls = append(f.varDecls, fmt.Sprintf("var %s = %s", name, init))
	return name
}

func (f *fileGen) funcs() template.FuncMap {
	funcs := template.FuncMap{
		"kind":   kindName,
		"goType": f.goType,
		"imp":    f.imp,
		"typeDoc": func(t *ir.Type) string {
			return typeDoc(t)
		},
		"fieldDoc":          fieldDoc,
		"tag":               tag,
		"streamDecodeStmts": f.streamDecodeStmts,
		"appendStmts":       f.appendStmts,
		"unionAppendStmts":  f.unionAppendStmts,

		"alternativeMethods": f.alternativeMethods,
		"propertyNameMethod": f.propertyNameMethod,
		"validateStmts":      f.validateStmts,
		"enumMessage":        enumMessage,
		"variantDoc":         variantDoc,

		"sealedDecls": f.sealedDecls,
		"opType": func(name string) string {
			return f.qualify(f.gen.lay.opsImport, f.gen.lay.opsPkg, name)
		},
		"unionDecodeStmts":   f.unionDecodeStmts,
		"unionMarshalStmts":  f.unionMarshalStmts,
		"unionValidateStmts": f.unionValidateStmts,
		"tupleDecls":         f.tupleDecls,
	}
	for name, fn := range f.serverFuncs() {
		funcs[name] = fn
	}
	for name, fn := range f.clientFuncs() {
		funcs[name] = fn
	}
	return funcs
}

func kindName(t *ir.Type) string {
	switch t.Kind {
	case ir.Struct:
		return "struct"
	case ir.Enum:
		return "enum"
	case ir.Defined:
		return "defined"
	case ir.Union:
		return "union"
	}
	return "alias"
}

// qualify refers to name, declared in the generated package with import
// path imp (named pkg), from the file being rendered.
func (f *fileGen) qualify(imp, pkg, name string) string {
	if imp == f.gen.self {
		return name
	}
	return f.imp(imp, pkg) + "." + name
}

// goType renders a type expression, recording the imports it needs.
func (f *fileGen) goType(r *ir.Ref) string {
	switch r.Kind {
	case ir.Builtin:
		if r.Import != "" {
			pkg, _, _ := strings.Cut(r.Name, ".")
			f.imp(r.Import, pkg)
		}
		return r.Name
	case ir.Named:
		return f.qualify(f.gen.lay.modelsImport, f.gen.lay.modelsPkg, r.Type.Name)
	case ir.Slice:
		return "[]" + f.goType(r.Elem)
	case ir.Map:
		return "map[string]" + f.goType(r.Elem)
	case ir.Optional:
		return f.imp(oapiImport, "oapi") + ".Optional[" + f.goType(r.Elem) + "]"
	case ir.Nullable:
		return f.imp(oapiImport, "oapi") + ".Nullable[" + f.goType(r.Elem) + "]"
	case ir.Pointer:
		return "*" + f.goType(r.Elem)
	case ir.Stream:
		return f.imp("iter", "iter") + ".Seq2[" + f.goType(r.Elem) + ", error]"
	case ir.Event:
		return f.imp(serverImport, "server") + ".TypedEvent[" + f.goType(r.Elem) + "]"
	case ir.Part:
		return f.imp(oapiImport, "oapi") + ".Part[" + f.goType(r.Elem) + "]"
	case ir.Tuple:
		return f.qualify(f.gen.lay.opsImport, f.gen.lay.opsPkg, r.Tuple.Name)
	}
	return "any"
}

func typeDoc(t *ir.Type) string {
	var lines []string
	where := t.Location.Pointer
	if where == "" {
		where = t.Location.File()
	}
	lines = append(lines, fmt.Sprintf("%s is generated from the schema at %s.", t.Name, where))
	if t.Doc != "" {
		lines = append(lines, "", t.Doc)
	}
	if t.Deprecated {
		lines = append(lines, "", "Deprecated: the schema is marked as deprecated.")
	}
	return comment("", lines)
}

func fieldDoc(fd *ir.Field) string {
	var lines []string
	if fd.Doc != "" {
		lines = append(lines, fd.Doc)
	}
	var notes []string
	if fd.ReadOnly {
		notes = append(notes, "Read-only: sent in responses only.")
	}
	if fd.WriteOnly {
		notes = append(notes, "Write-only: sent in requests only.")
	}
	if len(notes) > 0 {
		if len(lines) > 0 {
			lines = append(lines, "")
		}
		lines = append(lines, notes...)
	}
	if fd.Deprecated {
		if len(lines) > 0 {
			lines = append(lines, "")
		}
		lines = append(lines, "Deprecated: the property is marked as deprecated.")
	}
	return comment("\t", lines)
}

// comment renders lines as a // comment; embedded newlines start new
// comment lines.
func comment(indent string, lines []string) string {
	var b strings.Builder
	for _, l := range lines {
		for _, sub := range strings.Split(l, "\n") {
			sub = strings.TrimRightFunc(sub, unicode.IsSpace)
			if sub == "" {
				b.WriteString(indent + "//\n")
			} else {
				b.WriteString(indent + "// " + sub + "\n")
			}
		}
	}
	return strings.TrimSuffix(b.String(), "\n")
}

// tag returns the struct tag of a field. Optional values are left out of
// the output when absent.
func tag(fd *ir.Field) string {
	opt := ""
	switch {
	case fd.Required:
	case fd.Type.Kind == ir.Optional:
		opt = ",omitzero"
	default:
		opt = ",omitempty"
	}
	return "`json:" + strconv.Quote(fd.JSONName+opt) + "`"
}

func enumMessage(t *ir.Type) string {
	var values []string
	for _, v := range t.Values {
		values = append(values, v.Literal)
	}
	return strconv.Quote("must be one of " + strings.Join(values, ", "))
}

// fileName turns a type name into a file name, avoiding suffixes that the
// go command treats specially (_test, _windows, _amd64, ...).
func fileName(typeName string) string {
	var b strings.Builder
	rs := []rune(typeName)
	for i, r := range rs {
		if unicode.IsUpper(r) && i > 0 && (unicode.IsLower(rs[i-1]) || (i+1 < len(rs) && unicode.IsLower(rs[i+1]))) {
			b.WriteByte('_')
		}
		b.WriteRune(unicode.ToLower(r))
	}
	name := b.String()
	if i := strings.LastIndexByte(name, '_'); i >= 0 && buildSuffixes[name[i+1:]] {
		name += "_model"
	}
	return name + ".go"
}

// buildSuffixes are file name suffixes with a meaning to the go command.
var buildSuffixes = func() map[string]bool {
	m := map[string]bool{"test": true}
	for _, s := range strings.Fields(`aix android darwin dragonfly freebsd hurd illumos ios js linux nacl netbsd openbsd plan9 solaris wasip1 windows zos
		386 amd64 amd64p32 arm armbe arm64 arm64be loong64 mips mipsle mips64 mips64le mips64p32 mips64p32le ppc ppc64 ppc64le riscv riscv64 s390 s390x sparc sparc64 wasm`) {
		m[s] = true
	}
	return m
}()
